CREATE FUNCTION public.hotel_stay_value(room_name text, arrival date, departure date, extra_names text[]) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT COALESCE((SELECT sum((CASE room_name WHEN 'Classic Double' THEN 140 WHEN 'Superior Balcony' THEN 185 WHEN 'Family Suite' THEN 260 ELSE 340 END)*(CASE WHEN extract(month FROM d) BETWEEN 4 AND 10 THEN 1.2 ELSE 1 END)) FROM generate_series(arrival::timestamp,(departure-1)::timestamp,'1 day') d),0)+COALESCE((SELECT sum(CASE e WHEN 'Airport transfer' THEN 35 WHEN 'Celebration package' THEN 45 WHEN 'Late check-out' THEN 30 WHEN 'Bike rental' THEN 15*(departure-arrival) ELSE 0 END) FROM unnest(extra_names)e),0) $$;
INSERT INTO public.inquiries(guest_name,contact,created_at,call_started_at,call_ended_at,call_duration_sec,after_hours,nationality,age,gender,language,type_of_holiday,reason_for_stay,check_in,check_out,nights,adults,children,arrival_time,preferred_check_in_time,preferred_check_out_time,room_requested,recommended_room,recommended_extra,extras_interested,special_requests,estimated_value,priority,hesitation_reason,win_back_action,next_step,next_step_deadline,status,availability_status,summary,transcript,is_demo)
SELECT name,lower(replace(name,' ','.'))||'@example.com', t,t,t+interval '4 minutes',240,(extract(hour FROM t AT TIME ZONE 'Europe/Lisbon')<9 OR extract(hour FROM t AT TIME ZONE 'Europe/Lisbon')>=18),nat,28+(i*7)%38,CASE WHEN i%3=0 THEN 'Male' WHEN i%3=1 THEN 'Female' ELSE 'Not specified' END,lang,holiday,occasion,ci,ci+n,n,CASE WHEN i=2 THEN 2 ELSE 2 END,CASE WHEN i=2 THEN 2 ELSE 0 END,CASE WHEN i=3 THEN '23:00' ELSE '15:00' END,CASE WHEN i%9=0 THEN '12:00' ELSE '15:00' END,CASE WHEN i%7=0 THEN '14:00' ELSE '11:00' END,room,room,extra,ex,CASE WHEN i=1 THEN 'River view, private balcony and a little anniversary surprise' WHEN i=2 THEN 'Baby cot, two children, airport pickup' WHEN i=3 THEN 'Desk, fast Wi-Fi, invoice; flight lands at 23:00' ELSE 'Free rooftop welcome drink with direct booking' END,public.hotel_stay_value(room,ci,ci+n,ex),CASE WHEN i<=3 OR i%3=0 THEN 'hot' WHEN i%3=1 THEN 'warm' ELSE 'cold' END,CASE WHEN i=1 THEN 'Wants to be sure the balcony has a view' WHEN i=2 THEN 'Needs confirmation of a cot and airport pickup' WHEN i=3 THEN 'Worried about arriving after reception hours' WHEN i%3=0 THEN 'Waiting for room availability' WHEN i%3=1 THEN 'Comparing the price with Booking.com' ELSE 'Still finalizing travel dates' END,CASE WHEN i=1 THEN 'Send balcony photos and offer a rooftop welcome drink' WHEN i=2 THEN 'Confirm complimentary cot and arrange the €35 transfer' WHEN i=3 THEN 'Confirm late arrival, Wi-Fi and a business invoice' WHEN i%3=0 THEN 'Confirm availability and hold the room until noon' WHEN i%3=1 THEN 'Highlight free cancellation and the direct-booking welcome drink' ELSE 'Offer flexible dates and follow up by email' END,CASE WHEN i<=3 THEN 'Confirm availability by 10:00' ELSE 'Follow up with a personal room offer' END,date_trunc('day',now())+interval '10 hours'+((i%3)*30)*interval '1 minute',CASE WHEN i<=6 THEN 'new' WHEN i%4=0 THEN 'booked' WHEN i%4=1 THEN 'contacted' WHEN i%4=2 THEN 'lost' ELSE 'new' END,CASE WHEN i<=6 THEN 'to confirm' WHEN i%4=0 THEN 'confirmed' ELSE 'to confirm' END,name||' is planning a '||holiday||' stay for '||n||' nights. The concierge recommended the '||room||' with '||lower(extra)||'. Guest confirmed interest and would like the team to follow up.',jsonb_build_array(jsonb_build_object('speaker','Agent','text','Good evening, welcome to Casa Lisboa. How can I help you plan your stay?','timestamp','00:00'),jsonb_build_object('speaker','Guest','text',CASE WHEN i=1 THEN 'We are calling from New York. It is our anniversary and we would love a view, a balcony, and a little surprise.' WHEN i=2 THEN 'We are a family of four, including a baby. Could you arrange a cot and airport transfer?' WHEN i=3 THEN 'My flight lands at 23:00. I need a desk, fast Wi-Fi, and an invoice for work.' ELSE 'We are coming to Lisbon for a '||holiday||' and would love to stay for '||n||' nights.' END,'timestamp','00:18'),jsonb_build_object('speaker','Agent','text','I recommend our '||room||'. Breakfast and Wi-Fi are included, and '||lower(extra)||' would suit your trip. Your estimated stay total is €'||public.hotel_stay_value(room,ci,ci+n,ex)||'.','timestamp','01:02'),jsonb_build_object('speaker','Guest','text',CASE WHEN i<=3 THEN 'That sounds lovely. Could your team confirm availability and get back to me in the morning?' ELSE 'Let me confirm my plans. Please send me the details.' END,'timestamp','02:10'),jsonb_build_object('speaker','Agent','text','Of course. Our reservations team will follow up after 09:00 Lisbon time. Direct bookings also include a welcome drink at our rooftop bar.','timestamp','02:45'),jsonb_build_object('speaker','Guest','text','Perfect, thank you. You can contact me by email.','timestamp','03:22')),true
FROM (SELECT i,name,nat,lang,holiday,occasion,room,extra,ARRAY[extra]||CASE WHEN i=2 THEN ARRAY['Baby cot'] ELSE ARRAY[]::text[] END ex,CASE WHEN i<=6 THEN date_trunc('day',now())-interval '1 day'+(19+i%5)*interval '1 hour' ELSE now()-(7+i%53)*interval '1 day'+(i%12)*interval '1 hour' END t,CASE WHEN i=1 THEN (extract(year FROM now())::int+1||'-05-14')::date ELSE current_date+(i%25+2) END ci,CASE WHEN i=1 THEN 3 ELSE 2+i%5 END n FROM (VALUES
